snippet_css:
:root{
  --bg: #F6F2E8;
  --fg: #243020;
  --muted: #5E6B3A;
  --surface: rgba(255,255,255,.72);
  --border: rgba(36,48,32,.22);
  --accent: #7A5C2E;
  --accent-fg: #F6F2E8;
  --accent-grad: linear-gradient(135deg,#7A5C2E,#B08D57);
  --radius: 14px;
  --radius-sm: 8px;
  --shadow: 0 12px 28px rgba(36,48,32,.10);
  --btn-shadow: 0 4px 0 rgba(122,92,46,.26);
  --art-bg: linear-gradient(160deg,#E6E1D3,#B08D57 62%,#243020);
  --media-bg: linear-gradient(160deg,#F6F2E8,#D9D3C3);
  --cta-bg: linear-gradient(180deg,#F1ECE0,#E6E1D3);
  --input-bg: rgba(255,255,255,.92);
  --ok: #4E6146;
  --warn: #9C3B2E;
  --font-display: 'Cormorant','Noto Serif TC',serif;
  --font-body: 'Spectral','Noto Serif TC',serif;
  --font-mono: 'Spectral',ui-monospace,'SFMono-Regular',monospace;
  --focus-ring: var(--accent);
}

